	p.Name = strings.TrimSpace(p.Name)
	if p.UsageType == "" {
		p.UsageType = Licensed
	}
	p.Active = true
	if err := checkPlan(p); err != nil {
		return Plan{}, err
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.orgs[p.OrgID]; !ok {
		return Plan{}, ErrNotFound
	}
	p.ID = s.newID("plan")
	p.CreatedAt = now.UTC()
	s.plans[p.ID] = p
	return p, nil
}

