41	// describe is the invoice's first line, and how many more there are; an invoice without lines has no description.
42	func describe(lines []store.Line) string {
43		if len(lines) == 0 {
44			return ""
45		}
46		d := lines[0].Description
47		if len(lines) > 1 {
48			d += fmt.Sprintf(" and %d more", len(lines)-1)
49		}
50		return d
51	}
