94	func (s *Server) createInvoice(w http.ResponseWriter, r *http.Request, p auth.Principal) {
95		var in struct {
96			CustomerID      string         `json:"customer_id"`
97			Currency        money.Currency `json:"currency"`
98			Lines           []store.Line   `json:"lines"`
99			DiscountPercent int            `json:"discount_percent"`
100		}
101		if !decode(w, r, &in) {
102			return
103		}
104		if len(in.Lines) == 0 {
105			writeError(w, http.StatusUnprocessableEntity, "invalid", "an invoice needs at least one line")
106			return
107		}
108		for _, l := range in.Lines {
109			if strings.TrimSpace(l.Description) == "" || l.Quantity <= 0 || l.UnitAmount < 0 {
110				writeError(w, http.StatusUnprocessableEntity, "invalid", "each line needs a description, a positive quantity and a unit amount that is not negative")
111				return
112			}
113		}
114		inv, err := s.store.CreateInvoice(store.Invoice{OrgID: p.OrgID, CustomerID: in.CustomerID, Currency: in.Currency, Lines: in.Lines, DiscountPercent: in.DiscountPercent}, s.clock.Now())
115		if err != nil {
116			if errors.Is(err, store.ErrCustomerOrgMismatch) {
117				writeError(w, http.StatusUnprocessableEntity, "customer_org_mismatch", fmt.Sprintf("customer %s belongs to another organization", in.CustomerID))
118				return
119			}
120			s.storeError(w, err)
121			return
122		}
123		s.publish(r.Context(), p.OrgID, "invoice.created", map[string]any{"invoice_id": inv.ID})
124		writeJSON(w, http.StatusCreated, s.viewInvoice(inv))
125	}
